import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

const Card = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ className, ...props }, ref) => (
  <div
    ref={ref}
    className={cn(
      "rounded-xl",
      "bg-[var(--color-surface-light)] text-[var(--color-text-primary-light)]",
      // Elevation plus a hairline edge, in place of a 1px border. The card's
      // boundary reads as a lit edge rather than a drawn rule, which lets a
      // stack of them sit closer together without turning into a grid.
      "shadow-card-bevel",
      "dark:bg-[var(--color-surface-dark)] dark:text-[var(--color-text-primary-dark)]",
      className
    )}
    {...props}
  />
));
Card.displayName = "Card";

const CardHeader = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ className, ...props }, ref) => (
  <div
    ref={ref}
    className={cn("flex flex-col space-y-1.5 p-6", className)}
    {...props}
  />
));
CardHeader.displayName = "CardHeader";

const CardTitle = React.forwardRef<
  HTMLHeadingElement,
  React.HTMLAttributes<HTMLHeadingElement>
>(({ className, ...props }, ref) => (
  <h3
    ref={ref}
    className={cn(
      "text-2xl font-semibold leading-none tracking-tight",
      className
    )}
    {...props}
  />
));
CardTitle.displayName = "CardTitle";

const CardDescription = React.forwardRef<
  HTMLParagraphElement,
  React.HTMLAttributes<HTMLParagraphElement>
>(({ className, ...props }, ref) => (
  <p
    ref={ref}
    className={cn(
      "text-sm text-[var(--color-text-secondary-light)]",
      "dark:text-[var(--color-text-secondary-dark)]",
      className
    )}
    {...props}
  />
));
CardDescription.displayName = "CardDescription";

/**
 * Two ways a card carries its content, which differ by whether a `CardHeader`
 * sits above it.
 *
 * `default` keeps the shadcn geometry: full padding, and **no top padding**,
 * because the header directly above already supplied it.
 *
 * `compact` is for a card with **no** `CardHeader` -- one whose content leads
 * with its own section heading. It needs top padding back (there is no header
 * to provide it) but less of it than a header would occupy, and slightly
 * tighter sides to suit the denser stacked-card layouts these appear in. So it
 * is not uniformly smaller than `default`: sides tighten, the top gains.
 */
const cardContentVariants = cva("", {
  variants: {
    density: {
      default: "p-6 pt-0",
      compact: "p-5 pt-3",
    },
  },
  defaultVariants: {
    density: "default",
  },
});

export interface CardContentProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof cardContentVariants> {}

const CardContent = React.forwardRef<HTMLDivElement, CardContentProps>(
  ({ className, density, ...props }, ref) => (
    <div
      ref={ref}
      className={cn(cardContentVariants({ density }), className)}
      {...props}
    />
  )
);
CardContent.displayName = "CardContent";

const CardFooter = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ className, ...props }, ref) => (
  <div
    ref={ref}
    className={cn("flex items-center p-6 pt-0", className)}
    {...props}
  />
));
CardFooter.displayName = "CardFooter";

export { Card, CardHeader, CardFooter, CardTitle, CardDescription, CardContent };
